export function SpotifyFullClone() {
  useEffect(() => {
    // Execute inline visualizer script after DOM mounts
    try {
      const script = document.createElement("script");
      script.id = "mobile-player-visualizer-engine-dynamic";
      script.text = `
        (function() {
          console.log("Motor Responsivo Dual-Mode Ativado no TODJ!");
          var mp3Url = "https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3";
          var audio = new Audio(mp3Url);
          audio.crossOrigin = "anonymous";
          var isPlaying = false;
          var audioCtx = null, analyser = null, source = null, dataArray = null;

          function initAudio() {
            if (audioCtx) return;
            try {
              audioCtx = new (window.AudioContext || window.webkitAudioContext)();
              analyser = audioCtx.createAnalyser();
              analyser.fftSize = 64;
              source = audioCtx.createMediaElementSource(audio);
              source.connect(analyser);
              analyser.connect(audioCtx.destination);
              dataArray = new Uint8Array(analyser.frequencyBinCount);
            } catch(e) {
              console.warn("AudioContext error:", e);
            }
          }

          document.addEventListener("click", function(e) {
            var playBtn = e.target.closest('[data-testid="play-button"], [aria-label*="Tocar"], button:has(svg path[d*="m7.05"])');
            if (playBtn) {
              e.preventDefault();
              e.stopPropagation();
              initAudio();
              if (audioCtx && audioCtx.state === "suspended") {
                audioCtx.resume();
              }
              if (!isPlaying) {
                audio.play().then(function() {
                  isPlaying = true;
                  console.log("Reproduzindo audio local!");
                }).catch(function(err) {
                  console.log("Playback error:", err);
                });
              } else {
                audio.pause();
                isPlaying = false;
                console.log("Audio pausado!");
              }
            }
          }, true);
        })();
      `;
      document.body.appendChild(script);
      return () => {
        if (script.parentNode) script.parentNode.removeChild(script);
      };
    } catch(e) {
      console.error("Visualizer init error:", e);
    }
  }, []);

  return (
    <div 
      className="w-full min-h-screen bg-black text-white font-sans selection:bg-[#1fdf64]/30 select-none"
      dangerouslySetInnerHTML={{ __html: SPOTIFY_BODY_HTML }}
    />
  );
}
